#!/usr/bin/env python3
PREFIX = 'import Foundation\nimport Combine\n@MainActor enum MuteStore { static var muted = false; static func isMuted(_ id: String) -> Bool { muted } }\n@MainActor enum ChatPresence { static var openConversationId: String? }\n'
CHECKS = '@main struct Checks {\n @MainActor static func main() async {\n  let r = NotificationMessageRouter()\n  r.showBanner(conversationId: "a", messageId: "one", title: "A", body: "One")\n  let old = r.banner!\n  r.showBanner(conversationId: "b", messageId: "two", title: "B", body: "Two")\n  r.dismissBanner(old.id)\n  precondition(r.banner?.conversationId == "b")\n  r.dismissBanner()\n  r.showBanner(conversationId: "b", messageId: "two", title: "B", body: "Two")\n  precondition(r.banner == nil)\n  ChatPresence.openConversationId = "a"\n  r.showBanner(conversationId: "a", messageId: "three", title: "A", body: "Three")\n  precondition(r.banner == nil)\n  ChatPresence.openConversationId = nil\n  MuteStore.muted = true\n  r.showBanner(conversationId: "a", messageId: "four", title: "A", body: "Four")\n  precondition(r.banner == nil)\n  MuteStore.muted = false\n  r.open(conversationId: "a", messageId: "one")\n  let first = r.pendingConversation!\n  r.open(conversationId: "b", messageId: "two")\n  r.consumeConversation(first)\n  precondition(r.pendingConversation?.conversationId == "b")\n  r.consumeConversation(r.pendingConversation!)\n  precondition(r.pendingMessage?.messageId == "two")\n  r.resetForSignOut()\n  precondition(r.banner == nil && r.pendingConversation == nil && r.pendingMessage == nil)\n  var navigation: Task<Void, Never>?\n  var observedBeforeCommit = false\n  let subscription = r.$pendingConversation.sink { destination in\n   guard let destination else { return }\n   observedBeforeCommit = r.pendingConversation != destination\n   navigation = Task { @MainActor in\n    await Task.yield()\n    guard r.pendingConversation == destination else { return }\n    r.consumeConversation(destination)\n   }\n  }\n  r.open(conversationId: "cached-chat", messageId: "target-message")\n  await navigation?.value\n  precondition(observedBeforeCommit && r.pendingConversation == nil && r.pendingMessage?.messageId == "target-message")\n  subscription.cancel()\n  r.open(conversationId: "unavailable", messageId: "retry-message")\n  r.navigationFailed(r.pendingConversation!)\n  precondition(r.banner?.conversationId == "unavailable" && r.banner?.messageId == "retry-message")\n  r.resetForSignOut()\n  r.showBanner(conversationId: "burst", messageId: "1", title: "A", body: "First")\n  let stale = r.banner!\n  r.showBanner(conversationId: "burst", messageId: "2", title: "A", body: "Second")\n  r.dismissBanner(stale.id)\n  precondition(r.banner?.messageId == "2" && r.banner?.count == 2 && r.banners.count == 1)\n  r.showBanner(conversationId: "other", messageId: "3", title: "B", body: "Third")\n  r.dismissBanner(r.banner!.id)\n  precondition(r.banner?.conversationId == "burst" && r.banner?.messageId == "2")\n  r.showBanner(conversationId: "c", messageId: "4", title: "C", body: "Fourth")\n  r.showBanner(conversationId: "d", messageId: "5", title: "D", body: "Fifth")\n  r.showBanner(conversationId: "e", messageId: "6", title: "E", body: "Sixth")\n  precondition(r.banners.count == 3 && r.banner?.conversationId == "e")\n  print("iOS notification router: 12 regression checks passed")\n }\n}\n'
PREFIX += '@MainActor final class CommunityLinkRouter { static let shared = CommunityLinkRouter(); var lastURL: URL?; func handle(_ url: URL?) { lastURL = url } }\n'
CHECKS = CHECKS.replace('  print("iOS notification router: 12 regression checks passed")', '  r.resetForSignOut()\n  r.showCommunityApproval("test-community", isUpdate: true)\n  precondition(r.banner?.title == "New community update")\n  r.openBanner(r.banner!)\n  precondition(CommunityLinkRouter.shared.lastURL?.absoluteString == "https://voiid.app/c/test-community" && r.banner == nil)\n  print("iOS notification router: 14 regression checks passed")')
"""Compile production notification routing with isolated mute/presence fixtures."""
from pathlib import Path
import subprocess
import tempfile
root = Path(__file__).resolve().parents[1]
source = (root / 'apps/ios/Voiid/Voiid/VoiidApp.swift').read_text()
start = source.index('@MainActor\nfinal class NotificationMessageRouter')
end = source.index('/// AppDelegate forwards', start)
with tempfile.TemporaryDirectory(prefix='voiid-notification-checks-') as directory:
    path = Path(directory)
    swift = path / 'Checks.swift'
    swift.write_text(PREFIX + source[start:end] + CHECKS)
    subprocess.run(['swiftc', '-parse-as-library', str(swift), '-o', str(path / 'checks')], check=True)
    subprocess.run([str(path / 'checks')], check=True)
